<script setup lang="ts">
definePageMeta({ layout: 'admin', middleware: 'admin-auth' })
const { data: session } = await useFetch<any>('/api/admin/auth/session')
if (session.value?.user?.role !== 'super_admin') throw createError({ statusCode: 403, statusMessage: 'Akses ditolak' })
const { data: vouchers, refresh } = await useFetch<any[]>('/api/admin/vouchers')
const form = reactive({ code: '', type: 'fixed', value: 0, minimumSubtotal: 0, maximumDiscount: 0, quota: 0, startsAt: '', endsAt: '' })
const message = ref('')
const save = async () => { try { await $fetch('/api/admin/vouchers', { method: 'POST', body: { ...form, value: Number(form.value), minimumSubtotal: Number(form.minimumSubtotal), maximumDiscount: Number(form.maximumDiscount) || null, quota: Number(form.quota) || null } }); message.value = 'Voucher tersimpan.'; await refresh() } catch (error: any) { message.value = error?.data?.statusMessage || 'Gagal menyimpan voucher.' } }
const toggle = async (voucher: any) => { await $fetch(`/api/admin/vouchers/${voucher.id}`, { method: 'PATCH', body: { active: !voucher.active } }); voucher.active = voucher.active ? 0 : 1 }
const formatPrice = (price: number) => new Intl.NumberFormat('id-ID').format(price)
</script>
<template><div class="admin-page"><div class="admin-page-heading"><div><p class="eyebrow">Marketing</p><h1>Voucher.</h1></div></div><section class="admin-panel"><form class="admin-form" @submit.prevent="save"><div class="admin-form-grid"><label>Kode<input v-model="form.code" required /></label><label>Tipe<select v-model="form.type"><option value="fixed">Nominal</option><option value="percentage">Persentase</option></select></label><label>Nilai<input v-model.number="form.value" required min="1" type="number" /></label><label>Minimum subtotal<input v-model.number="form.minimumSubtotal" min="0" type="number" /></label><label>Maksimum diskon<input v-model.number="form.maximumDiscount" min="0" type="number" /></label><label>Quota<input v-model.number="form.quota" min="0" type="number" /></label><label>Mulai<input v-model="form.startsAt" required type="datetime-local" /></label><label>Selesai<input v-model="form.endsAt" required type="datetime-local" /></label></div><button class="button button-dark">Simpan voucher</button><p v-if="message" role="status">{{ message }}</p></form></section><section class="admin-panel"><table class="admin-table"><thead><tr><th>Kode</th><th>Diskon</th><th>Periode</th><th>Dipakai</th><th>Status</th></tr></thead><tbody><tr v-for="voucher in vouchers" :key="voucher.id"><td><strong>{{ voucher.code }}</strong></td><td>{{ voucher.type === 'percentage' ? `${voucher.value}%` : `Rp ${formatPrice(voucher.value)}` }}</td><td>{{ new Date(voucher.startsAt).toLocaleDateString('id-ID') }} – {{ new Date(voucher.endsAt).toLocaleDateString('id-ID') }}</td><td>{{ voucher.used }}{{ voucher.quota ? ` / ${voucher.quota}` : '' }}</td><td><button class="status-toggle" :class="{ 'is-active': voucher.active }" @click="toggle(voucher)">{{ voucher.active ? 'Aktif' : 'Nonaktif' }}</button></td></tr></tbody></table></section></div></template>
